use super::*;

/// The registry AND its gaps, as one value — because a caller that got the accounts without knowing
/// what is missing from them would compute a confident number over a partial picture.
pub fn accounts_json(accounts: &[Account], rejected: &[String]) -> serde_json::Value {
    let (known, possible) = account::completeness(accounts);
    serde_json::json!({
        "accounts": account::all_to_json(accounts),
        "gaps": account::gaps(accounts).iter().map(|g| serde_json::json!({
            "account": g.account, "field": g.field, "blocks": g.blocks,
        })).collect::<Vec<_>>(),
        "known": known,
        "knowable": possible,
        "unreadable": rejected,
    })
}
